using ghidra.util.task;

public class DebuggerCopyPlan {
	public interface Copier {
		string getName();

		bool isAvailable(TraceProgramView from, Program into);

		Collection<Copier> getRequires();

		Collection<Copier> getRequiredBy();

		bool isRequiresInitializedMemory();

		void copy(TraceProgramView from, AddressRange fromRange, Program into, Address intoAddress,
				TaskMonitor monitor);
	}

	public class AllCopiers : Copier
{	public static readonly AllCopiers BYTES = new(, List.of();
	public static readonly AllCopiers STATE = new(, List.of();
	public static readonly AllCopiers INSTRUCTIONS = new(, List.of(BYTES);
	public static readonly AllCopiers DATA = new(, List.of();
	public static readonly AllCopiers DYNAMIC_DATA = new(, List.of(BYTES);
	public static readonly AllCopiers LABELS = new(, List.of();
	public static readonly AllCopiers BREAKPOINTS = new(, List.of();
	public static readonly AllCopiers BOOKMARKS = new(, List.of();
	public static readonly AllCopiers REFERENCES = new(, List.of();
	public static readonly AllCopiers COMMENTS = new(, List.of();


		protected bool sameDataOrganization(Program p1, Program p2) {
			DataOrganization dataOrg1 = p1.getDataTypeManager().getDataOrganization();
			DataOrganization dataOrg2 = p2.getDataTypeManager().getDataOrganization();
			return dataOrg1.equals(dataOrg2);
		}

		public static readonly List<Copier> VALUES;
		static DebuggerCopyPlan() {
			List<AllCopiers> asList = Arrays.asList(values());
			Collections.sort(asList, Comparator.comparing(AllCopiers.getName));
			VALUES = Collections.unmodifiableList(asList);
		}

		string name;
		Collection<Copier> requires;
		Collection<Copier> requiredBy = new();

		private AllCopiers(string name, Collection<AllCopiers> requires) {
			this.name = name;
			this.requires = Collections.unmodifiableCollection(requires);
			foreach (AllCopiers req in requires) {
				req.requiredBy.add(this);
			}
		}

		protected bool checkAvailable(TraceProgramView from, Program into) {
			return true;
		}

		/* @Override */
		public bool isAvailable(TraceProgramView from, Program into) {
			return checkAvailable(from, into) &&
				getRequires().stream().allMatch(c => c.isAvailable(from, into));
		}

		/* @Override */
		public string getName() {
			return name;
		}

		/* @Override */
		public Collection<Copier> getRequires() {
			return requires;
		}

		/* @Override */
		public Collection<Copier> getRequiredBy() {
			return requiredBy;
		}

		/* @Override */
		public bool isRequiresInitializedMemory() {
			return false;
		}
	}

	protected Map<Copier, JCheckBox> checkBoxes = new();

	public DebuggerCopyPlan() {
		foreach (Copier copier in getAllCopiers()) {
			JCheckBox cb = new JCheckBox(copier.getName());
			Collection<Copier> requires = copier.getRequires();
			Collection<Copier> requiredBy = copier.getRequiredBy();
			if (!requires.isEmpty() || !requiredBy.isEmpty()) {
				cb.addActionListener(e => {
					if (cb.isSelected()) {
						foreach (Copier req in requires) {
							checkBoxes.get(req).setSelected(true);
						}
					}
					else {
						foreach (Copier dep in requiredBy) {
							checkBoxes.get(dep).setSelected(false);
						}
					}
				});
			}
			checkBoxes.put(copier, cb);
		}
	}

	public Collection<Copier> getAllCopiers() {
		return AllCopiers.VALUES;
	}

	public JCheckBox getCheckBox(Copier copier) {
		return checkBoxes.get(copier);
	}

	public void selectAll() {
		foreach (JCheckBox cb in checkBoxes.values()) {
			cb.setSelected(true);
		}
	}

	public void selectNone() {
		foreach (JCheckBox cb in checkBoxes.values()) {
			cb.setSelected(false);
		}
	}

	public void execute(TraceProgramView from, AddressRange fromRange, Program into,
			Address intoAddress, TaskMonitor monitor)
    {
		foreach (Copier copier in getAllCopiers()) {
			if (!copier.isAvailable(from, into)) {
				continue;
			}
			if (!checkBoxes.get(copier).isSelected()) {
				continue;
			}
			copier.copy(from, fromRange, into, intoAddress, monitor);
		}
	}

	public void syncCopiersEnabled(TraceProgramView from, Program dest) {
		foreach (Map.Entry<Copier, JCheckBox> ent in checkBoxes.entrySet()) {
			ent.getValue().setEnabled(ent.getKey().isAvailable(from, dest));
		}
	}

	public bool isRequiresInitializedMemory(TraceProgramView from, Program dest) {
		return checkBoxes.entrySet().stream().anyMatch(ent => {
			Copier copier = ent.getKey();
			return copier.isRequiresInitializedMemory() && copier.isAvailable(from, dest) &&
				ent.getValue().isSelected();
		});
	}
}
